import{_ as r,o as t,c as o,a5 as a}from"./chunks/framework.BZzouRtU.js";const s="/study/images/browser/worker-message-flow.svg",d="/study/images/browser/worker-copy-transfer.svg",k=JSON.parse('{"title":"Web Workerとメッセージ通信 — 実行の分担とデータの所有権","description":"","frontmatter":{"title":"Web Workerとメッセージ通信 — 実行の分担とデータの所有権","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"browser","summary":"Dedicated Workerの実行環境とメッセージ通信を説明する。structured cloneとArrayBufferの移譲、送信時の処理と受信イベント、返信の識別、エラー、終了とキャンセルを分け、処理場所とデータ所有権の境界を整理する。","aliases":["Web Worker","Dedicated Worker","WorkerGlobalScope","DedicatedWorkerGlobalScope","agent","postMessage","message","structured clone","structured serialization","transfer","transferable","transfer list","ArrayBuffer","detach","DataCloneError","messageerror","terminate","generation","世代","協調キャンセル"],"verification":"一次資料照合（2026-11-04）"}},"headers":[],"relativePath":"browser/web-workers-messages.md","filePath":"browser/web-workers-messages.md"}'),l={name:"browser/web-workers-messages.md"};function n(c,e,i,p,h,g){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="web-workerとメッセージ通信-—-実行の分担とデータの所有権" tabindex="-1">Web Workerとメッセージ通信 — 実行の分担とデータの所有権 <a class="header-anchor" href="#web-workerとメッセージ通信-—-実行の分担とデータの所有権" aria-label="Permalink to &quot;Web Workerとメッセージ通信 — 実行の分担とデータの所有権&quot;">​</a></h1><p><strong>Web Worker</strong>は、ページのJavaScriptとは別の実行環境でスクリプトを動かす仕組みです。重い計算などを分担し、その結果をメッセージでページへ返せます。使うときは、どちらで処理を実行するかと、ページとWorkerのどちらがデータを使えるかを分けて考えます。</p><p><a href="/study/browser/event-loop-promises.html">イベントループ・Promise・async/await</a>で説明したとおり、Promiseで包むだけでは計算を別の実行主体へ移せません。Workerは、その実行主体を分けるための別のAPIです。ここでは、作成元との専用の通信経路を持つ<strong>Dedicated Worker</strong>を対象にし、Node.jsのworkerやC#のTaskへ同じ規則を一般化しません。</p><h2 id="ページとworkerには、別のグローバル環境がある" tabindex="-1">ページとWorkerには、別のグローバル環境がある <a class="header-anchor" href="#ページとworkerには、別のグローバル環境がある" aria-label="Permalink to &quot;ページとWorkerには、別のグローバル環境がある&quot;">​</a></h2><p>ページ側のグローバル環境はWindow、Dedicated Worker側は<strong>DedicatedWorkerGlobalScope</strong>です。Workerには別の実行スタックやイベントループがあり、言語仕様上の<strong>agent</strong>という実行主体に対応します。ページの関数や変数を自由に参照する環境ではありません。<a href="https://html.spec.whatwg.org/multipage/workers.html#run-a-worker" target="_blank" rel="noreferrer">WHATWG HTML: Workersの処理モデル</a>、<a href="https://tc39.es/ecma262/multipage/executable-code-and-execution-contexts.html#sec-agents" target="_blank" rel="noreferrer">ECMAScript: Agents</a></p><p>Workerからページの<code>document</code>やDOMを直接操作したり、ページのWindowオブジェクトを直接使ったりはできません。Worker側では<code>self</code>や<code>globalThis</code>を通じて自分のグローバル環境を扱います。タイマーや<code>fetch</code>など利用できるAPIもありますが、ページとすべて同じAPIがあるわけではありません。結果を受けたページ側がDOMを更新し、その後に<a href="/study/browser/rendering-journey.html">描画の更新</a>へつながります。<a href="https://developer.mozilla.org/en-US/docs/Web/API/Web_Workers_API/Using_web_workers#web_workers_api" target="_blank" rel="noreferrer">MDN: Using Web Workers</a></p><p>Workerとページは独立して進み、環境に応じて同時並行に実行できます。ただし、APIのWorker一つと、特定のOSスレッドやプロセスが常に固定の一対一になるという配置を、アプリの前提にしません。仕様上のagentやevent loopと、ブラウザ実装の実行資源は区別します。<a href="https://html.spec.whatwg.org/multipage/webappapis.html#event-loops" target="_blank" rel="noreferrer">WHATWG HTML: Event loopsと実装スレッド</a></p><p>また、起動、スクリプトの取得・解析、メモリ、データ受け渡しの負担が増えます。短い計算を細かく送ると、受け渡しの方が大きな仕事になる場合もあります。Workerを増やせば常に速くなる、コア数に比例して速くなる、という保証はありません。<a href="https://html.spec.whatwg.org/multipage/workers.html#workers" target="_blank" rel="noreferrer">WHATWG HTML: Workersの用途とコスト</a></p><h2 id="起動要求と、アプリとして準備できたこと" tabindex="-1">起動要求と、アプリとして準備できたこと <a class="header-anchor" href="#起動要求と、アプリとして準備できたこと" aria-label="Permalink to &quot;起動要求と、アプリとして準備できたこと&quot;">​</a></h2><p><code>new Worker(&quot;worker.js&quot;)</code>は、Workerを作り、その外側の通信窓口になるWorkerオブジェクトを返します。外部スクリプトの取得や初期化がすべて終わるまで、呼び出し元で同期的に待ち続けるAPIではありません。URLや配信条件の問題で起動に失敗したり、取得したスクリプトが実行時に失敗したりする場合もあります。</p><p>初期化の完了を確認するため、<strong>readyハンドシェイク</strong>を使えます。Workerが受信処理や必要なデータを準備して<code>{ type: &quot;ready&quot; }</code>などを送り、ページは受信後に要求を送ります。これはアプリの約束で、APIに決まった<code>ready</code>イベントがあるわけではありません。受信処理とエラー処理も用意します。<a href="https://html.spec.whatwg.org/multipage/workers.html#dom-worker" target="_blank" rel="noreferrer">WHATWG HTML: Workerの生成と実行</a></p><p>この章の付属例は、ページと外部classic worker scriptを同じoriginのHTTP/HTTPSで配信します。手元で試すときも、サンプルに記載したローカルHTTPサーバーから開きます。Workerにはmodule版もあり、スクリプトの種類と読み込み方を区別して使います。</p><h2 id="postmessageは、相手の関数を直接呼ばない" tabindex="-1">postMessageは、相手の関数を直接呼ばない <a class="header-anchor" href="#postmessageは、相手の関数を直接呼ばない" aria-label="Permalink to &quot;postMessageは、相手の関数を直接呼ばない&quot;">​</a></h2><p>ページからは<code>worker.postMessage(data)</code>、Worker側からは<code>self.postMessage(data)</code>などで送信します。受信側では、後の<code>message</code>イベントの<code>event.data</code>としてデータを受け取ります。呼び出し元のスタックをそのまま相手へ渡し、その関数の戻り値を受け取る仕組みではありません。<a href="https://developer.mozilla.org/en-US/docs/Web/API/Worker/postMessage" target="_blank" rel="noreferrer">MDN: Worker.postMessage</a></p><p>送信側では、呼び出し中にデータの<strong>シリアライズ</strong>や移譲の手続きを行います。シリアライズは、別の環境で値を再構成できる表現へ変換することです。受信側の処理は後ですが、送る準備まで全部が後回しになるわけではありません。大きなオブジェクトの送信が、送信元にとって無料の操作になるとも限りません。受信側のイベントループで、メッセージの復元と配送へ進みます。<a href="https://html.spec.whatwg.org/multipage/web-messaging.html#dom-messageport-postmessage" target="_blank" rel="noreferrer">WHATWG HTML: MessagePortのpostMessage</a></p><p>正常に<code>postMessage</code>から戻っても、相手が受信・計算・表示まで完了したという証拠にはなりません。返信が必要なら、結果や受領確認を別のメッセージとして返すプロトコルを設計します。</p><figure><img src="'+s+'" alt="ページとDedicated Workerの別の実行環境、ready通知、postMessageの送信時処理、後の受信と結果返信、ページ側のDOM更新を示す図" width="760" height="1510" loading="lazy"><figcaption><code>postMessage</code>は、相手の関数をその場で実行する呼び出しではありません。送信手続き、受信イベント、アプリの処理完了、DOM更新と表示を分けます。<a href="/study/images/browser/worker-message-flow.svg" target="_blank" rel="noopener">図を拡大する</a></figcaption></figure><h2 id="structured-cloneは、何でもそのまま複製する仕組みではない" tabindex="-1">structured cloneは、何でもそのまま複製する仕組みではない <a class="header-anchor" href="#structured-cloneは、何でもそのまま複製する仕組みではない" aria-label="Permalink to &quot;structured cloneは、何でもそのまま複製する仕組みではない&quot;">​</a></h2><p>Worker間のデータ受け渡しには<strong>structured clone</strong>の仕組みを使います。JSON文字列への変換だけを行う方式ではなく、配列、通常のオブジェクト、Map、Set、Date、ArrayBuffer、型付き配列など、対応する型を扱えます。対応する構造なら循環参照も処理できます。</p><p>一方、関数やDOMノードはそのまま送れず、<code>DataCloneError</code>の原因になります。独自クラスのプロトタイプ、プロパティの属性、getter／setterの定義なども、元のオブジェクトの全性質が再現されるわけではありません。「関数を送ってWorkerでそのまま実行する」「DOM要素を送って向こうで書き換える」という使い方にはなりません。処理内容はWorkerのスクリプトに用意し、メッセージでは処理の種類や入力データを渡します。<a href="https://developer.mozilla.org/en-US/docs/Web/API/Web_Workers_API/Structured_clone_algorithm" target="_blank" rel="noreferrer">MDN: Structured cloneの対応型と制限</a></p><p>通常のオブジェクトやArrayBufferのコピーでは、受信側で再構成したデータを変更しても、送信元の元データを共有して変更することにはなりません。ただし、共有メモリを持つSharedArrayBufferのような別の仕組みまで「すべて必ず独立コピー」と一般化しません。<a href="https://html.spec.whatwg.org/multipage/structured-data.html#structuredserializeinternal" target="_blank" rel="noreferrer">WHATWG HTML: StructuredSerializeInternal</a></p><h2 id="arraybufferのコピーと移譲" tabindex="-1">ArrayBufferのコピーと移譲 <a class="header-anchor" href="#arraybufferのコピーと移譲" aria-label="Permalink to &quot;ArrayBufferのコピーと移譲&quot;">​</a></h2><p><strong>ArrayBuffer</strong>は、バイト列の領域を表すオブジェクトです。Uint8Arrayなどの型付き配列は、その領域を特定の型として読む<strong>ビュー</strong>です。通常のコピーと、<strong>transfer</strong>による移譲では、送信元がその後に領域を使えるかが異なります。</p><table tabindex="0"><thead><tr><th>送信方法</th><th>受信側と送信元の関係</th></tr></thead><tbody><tr><td>transfer listなしでArrayBufferを送る</td><td>受信側が独立した内容を得て、送信元も元の領域を使える</td></tr><tr><td>ArrayBufferをtransfer listへ入れて送る</td><td>領域の利用を受信側へ移し、送信元のArrayBufferはdetachされる</td></tr></tbody></table><p><code>worker.postMessage({ buffer }, [buffer])</code>とすると、本文に含むArrayBufferを移譲の対象にします。成功後の送信元では<code>buffer.byteLength</code>が0になり、元の領域を通常どおり読み書きできません。同じ領域を参照する型付き配列にも影響します。これは<code>const</code>変数の代入可否とは別で、領域との結びつきを切る<strong>detach</strong>という状態変化です。最初から空のバッファも長さ0なので、この値だけを一般的なdetach判定にはしません。<a href="https://tc39.es/ecma262/multipage/structured-data.html#sec-detacharraybuffer" target="_blank" rel="noreferrer">ECMAScript: DetachArrayBuffer</a></p><p>transfer listへ入れるのはUint8Arrayそのものではなく、通常はその<code>buffer</code>です。また、リストは「この資源を移譲する」という指定であり、それだけでメッセージ本文へ追加するものではありません。ArrayBufferを本文からたどれない形でリストにだけ入れると、送信元はdetachされても、受信したデータからそのバッファを使えない形になり得ます。<a href="https://developer.mozilla.org/en-US/docs/Web/API/Web_Workers_API/Transferable_objects" target="_blank" rel="noreferrer">MDN: Transferable objects</a>、<a href="https://developer.mozilla.org/en-US/docs/Web/API/Worker/postMessage#parameters" target="_blank" rel="noreferrer">MDN: transfer引数</a></p><p>移譲して返しても、元のJavaScriptのArrayBufferオブジェクト自体が復活するわけではありません。受信側では別のオブジェクトとして領域を扱います。データ領域の移譲と、JavaScriptの参照の同一性は区別します。コピーの削減につながる仕組みですが、今回のAPI観察だけから、プロセス間の物理的なコピー回数や「常に完全なzero-copy」を証明したことにはしません。<a href="https://html.spec.whatwg.org/multipage/structured-data.html#structuredserializewithtransfer" target="_blank" rel="noreferrer">WHATWG HTML: StructuredSerializeWithTransfer / StructuredDeserializeWithTransfer</a></p><figure><img src="'+d+'" alt="ArrayBufferをコピーした場合の独立したデータと、移譲した場合の送信元detach、受信側の新しいオブジェクト、返信で移譲し直す関係を示す図" width="760" height="1510" loading="lazy"><figcaption>コピーは両側が独立した内容を扱い、移譲は領域の利用を受け渡します。移譲後の返信も、元のJavaScriptオブジェクトの復活ではありません。<a href="/study/images/browser/worker-copy-transfer.svg" target="_blank" rel="noopener">図を拡大する</a></figcaption></figure><h2 id="返信には種類、要求id、世代、完了条件を持たせる" tabindex="-1">返信には種類、要求ID、世代、完了条件を持たせる <a class="header-anchor" href="#返信には種類、要求id、世代、完了条件を持たせる" aria-label="Permalink to &quot;返信には種類、要求ID、世代、完了条件を持たせる&quot;">​</a></h2><p>メッセージに<code>type</code>で種類、<code>id</code>で要求、<code>generation</code>でWorkerや画面状態の世代を持たせると、返信を識別できます。これらはアプリが定義する項目で、Worker APIが自動で付けるものではありません。</p><p>世代はメッセージの項目に含めるほか、作成元で受信コールバックとWorkerの世代を結び付けて管理する方法もあります。付属例は後者で、ページ側のsessionに世代とWorkerオブジェクトを保持し、受信時に照合します。</p><p>例えば「処理を要求」「結果」「受領確認」「処理失敗」を区別します。<strong>ack</strong>は受領や処理の確認を表す返信ですが、単に受け取った確認なのか、計算終了なのか、結果の反映まで済んだのかを決めます。種類やID、内容の型や長さを検証してから、対応する要求を完了扱いにします。大量に要求を送り続ける場合は、待ち行列やメモリが増えないよう、同時に待つ要求数も制限する設計が必要です。</p><p>同じ通信経路でのメッセージ配送順と、仕事の完了・返信順も別です。受信処理で<code>await</code>を使うなど、複数の仕事が途中で待つ設計なら、後の要求が先に完了する場合があります。</p><p>複数のWorkerを再利用し、実行枠と待機数を制限する設計は、<a href="/study/browser/worker-pool-backpressure.html">Worker poolと待ち行列の制御</a>で扱います。依頼を受け付けたことと、Workerへ送って実行中になったことを分けます。</p><p>Workerの作り直しや画面切り替え後に、世代を照合して古い返信を無視する方法は、<strong>結果の採用を止める仕組み</strong>です。古いWorkerの計算自体を停止したことにはなりません。</p><h2 id="送信時の例外、error、messageerrorを分ける" tabindex="-1">送信時の例外、error、messageerrorを分ける <a class="header-anchor" href="#送信時の例外、error、messageerrorを分ける" aria-label="Permalink to &quot;送信時の例外、error、messageerrorを分ける&quot;">​</a></h2><table tabindex="0"><thead><tr><th>失敗の経路</th><th>区別すること</th></tr></thead><tbody><tr><td><code>new Worker</code>や<code>postMessage</code>の同期例外</td><td>呼び出し側の<code>try</code>／<code>catch</code>で扱う。送れないデータによるDataCloneErrorなど</td></tr><tr><td>Workerの<code>error</code>イベント</td><td>スクリプトの実行などで発生したエラーの通知</td></tr><tr><td><code>messageerror</code>イベント</td><td>受信メッセージをデシリアライズできなかったことの通知</td></tr><tr><td>アプリの失敗返信</td><td>データとして定義した処理失敗。上のAPIエラーとは別</td></tr></tbody></table><p><strong>デシリアライズ</strong>は、受け渡された表現から受信側の値を復元する処理です。<code>postMessage</code>を囲んだ<code>try</code>／<code>catch</code>だけで、後のWorker内の例外まで捕まえられるわけではありません。また、受信データの形式がアプリの約束と違うことが、必ず<code>messageerror</code>になるわけでもありません。<a href="https://developer.mozilla.org/en-US/docs/Web/API/Worker/error_event" target="_blank" rel="noreferrer">MDN: Worker error</a>、<a href="https://developer.mozilla.org/en-US/docs/Web/API/Worker/messageerror_event" target="_blank" rel="noreferrer">MDN: Worker messageerror</a></p><h2 id="terminate、close、協調キャンセル" tabindex="-1">terminate、close、協調キャンセル <a class="header-anchor" href="#terminate、close、協調キャンセル" aria-label="Permalink to &quot;terminate、close、協調キャンセル&quot;">​</a></h2><p>ページ側の<code>worker.terminate()</code>は、Workerの処理を終了させます。現在のスクリプトの中断や未処理taskの破棄を伴い、Worker側の<code>finally</code>や終了前の返信が完走する前提にはできません。返信前に終了させても、移譲済みの送信元バッファは復活しません。待っている要求の管理やUIの復旧も、アプリ側の仕事です。<a href="https://html.spec.whatwg.org/multipage/workers.html#terminate-a-worker" target="_blank" rel="noreferrer">WHATWG HTML: Terminate a worker</a>、<a href="https://developer.mozilla.org/en-US/docs/Web/API/Worker/terminate" target="_blank" rel="noreferrer">MDN: terminate</a></p><p>Worker側の<code>self.close()</code>は、自分のキューにあるtaskを破棄し、以後のtaskを受け付けない閉鎖状態へ進めます。これは今のコードを任意の位置で強制中断する呼び出しではありません。必要な片付けを自分で行って閉じる設計と、外側からのterminateは区別します。<a href="https://developer.mozilla.org/en-US/docs/Web/API/DedicatedWorkerGlobalScope/close" target="_blank" rel="noreferrer">MDN: DedicatedWorkerGlobalScope.close</a></p><p><strong>協調キャンセル</strong>は、Workerが取消要求を受け取り、安全な区切りで仕事を止める方式です。ただし、長い同期ループの最中には、取消メッセージの受信taskも実行できません。処理を区切って受信の機会を作るなどの設計が必要で、fulfilledのPromiseをawaitし続けるだけでは、その機会を保証しません。</p><p>返信待ちのタイマーが切れても、計算が止まった証拠にはなりません。ページ側のタイマー自体がイベントループや非表示状態などで遅れる場合もあるため、<strong>soft timeout</strong>として、どの状態へ移すかを決めます。タイムアウト、世代による結果の無視、協調キャンセル、terminateは、それぞれ違う操作です。</p><h2 id="この章の観察範囲と、別の共有方式" tabindex="-1">この章の観察範囲と、別の共有方式 <a class="header-anchor" href="#この章の観察範囲と、別の共有方式" aria-label="Permalink to &quot;この章の観察範囲と、別の共有方式&quot;">​</a></h2><p><a href="/study/practice/browser/worker-message-observation.html">Workerのコピーと移譲の実践</a>では、HTTP配信したページと外部classic Workerで、ready、要求と返信、既知の非空ArrayBufferのコピーと移譲前後を観察します。DOMの更新はページ側です。この観測から、OSスレッド数、速度向上、物理コピー回数、画面への表示完了までは判断しません。</p><p>同じデータ領域を複数の実行主体で使う場合は、SharedArrayBufferとAtomicsが関わります。ブラウザの条件と、コピーした場合との実験は<a href="/study/browser/cross-origin-isolation.html">クロスオリジン分離と共有メモリ</a>で扱います。要求の仲介やオフライン対応は<a href="/study/browser/service-worker-offline.html">Service Workerとオフライン動作</a>を参照してください。</p>',46)])])}const u=r(l,[["render",n]]);export{k as __pageData,u as default};
